const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],clamp=(v,min,max)=>Math.min(max,Math.max(min,v)),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const CREDENTIALS={user:'admin',password:'quiz123'},STORAGE_KEY='quizrounds_sim_v30_state',SESSION_KEY='quizrounds_sim_v30_admin';
const DEFAULT_QUESTIONS=[
{id:'q1',type:'choice',prompt:'Qual planeta é conhecido como Planeta Vermelho?',options:{A:'Vênus',B:'Marte',C:'Júpiter',D:'Mercúrio'},correct:'B',points:1000,time:20,category:'Ciência',difficulty:'facil',speedBonus:20,scoreEnabled:true,tiebreaker:false,notes:'Marte recebe o apelido pela presença de óxidos de ferro.'},
{id:'q2',type:'numeric',prompt:'Quantos minutos existem em 2 horas e 30 minutos?',correctNumber:150,points:1000,time:20,category:'Matemática',difficulty:'medio',speedBonus:0,scoreEnabled:true,tiebreaker:false,notes:'2h30 = 150 minutos.'},
{id:'q3',type:'choice',prompt:'Qual é a capital do Brasil?',options:{A:'Brasília',B:'São Paulo',C:'Rio de Janeiro',D:'Salvador'},correct:'A',points:1000,time:15,category:'Geografia',difficulty:'facil',speedBonus:25,scoreEnabled:true,tiebreaker:false,notes:'Brasília é a capital federal desde 1960.'},
{id:'q4',type:'numeric',prompt:'Qual é o resultado de 25 × 8?',correctNumber:200,points:1200,time:15,category:'Matemática',difficulty:'medio',speedBonus:0,scoreEnabled:true,tiebreaker:true,notes:'Pode ser usada como desempate.'},
{id:'q5',type:'choice',prompt:'Qual destes é um protocolo usado na Web?',options:{A:'HTTP',B:'RPM',C:'PSI',D:'RPMI'},correct:'A',points:1000,time:20,category:'Tecnologia',difficulty:'medio',speedBonus:20,scoreEnabled:true,tiebreaker:false,notes:'HTTP é o Hypertext Transfer Protocol.'},
{id:'q6',type:'choice',prompt:'Qual símbolo representa uma alternativa em formato de triângulo?',options:{A:'▲',B:'◆',C:'●',D:'■'},correct:'A',points:1,time:12,category:'Diversão',difficulty:'facil',speedBonus:0,scoreEnabled:false,tiebreaker:false,notes:'Pergunta sem pontuação para demonstrar o modo diversão.'}
];
let db={questions:structuredClone(DEFAULT_QUESTIONS),selected:['q1','q2','q3','q4','q5'],title:'Quiz Teste Local',pin:'482731',rounds:5,botCount:50,accuracy:.65,profile:'normal',speed:5,failure:0,randomize:false,classification:true,qualifyTop:5,autoClose:false,streak:true,lateJoin:'allow_zero',theme:'violet',avatarScene:'office'};
